"""Lists every item the situation owners still have to check against the source PDFs
(Section 9 [VERIFY] tags, missing page numbers, unchecked agreement/evidence labels,
unsourced steps). Writes docs/VERIFY.md.

    python scripts/verify_report.py
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from app import content  # noqa: E402

OUT = ROOT.parent / "docs" / "VERIFY.md"


def main() -> None:
    lines = [
        "# Verification checklist",
        "",
        "Generated by `backend/scripts/verify_report.py` from the content files. Each situation owner checks every",
        "item against the source PDF, fills the exact page, sets `agreement` and `evidence`, sets `verified: true`,",
        "and finally marks the record `review_status: team_checked` (Section 18, phase 5).",
        "G1 page numbers currently in the records are section start pages from its table of contents, not the exact page.",
        "",
    ]
    total = 0
    for sid, rec in content.situations().items():
        lines += [f"## {rec['names']['en']} · `{sid}` · owner: {rec['owner']} · status: `{rec['review_status']}`", ""]
        lines += ["| Step | Text | Source | To do |", "|---|---|---|---|"]
        for bkey, b in rec["branches"].items():
            seen = set()
            for s in b["steps"]:
                if s["id"] in seen:
                    continue
                seen.add(s["id"])
                todo = []
                if s.get("verify_note"):
                    todo.append(s["verify_note"])
                if (s.get("check") or {}).get("verify_note"):
                    todo.append("Yes/No check: " + s["check"]["verify_note"])
                if s["source"]["doc"] == "UNSOURCED":
                    todo.append("**source needed**")
                elif s["source"].get("page") is None:
                    todo.append("page number")
                if s["agreement"] == "unchecked":
                    todo.append("agreement")
                if s["evidence"] == "unchecked":
                    todo.append("evidence")
                if not s["verified"]:
                    todo.append("verified flag")
                img = s.get("image")
                if img and not img.get("verified"):
                    todo.append(f"picture matches step ({img['file']})")
                an = s.get("animation")
                if an and not an.get("verified"):
                    todo.append(f"movement matches guideline ({an['file']})")
                aid = s.get("aid")
                if aid:
                    todo.append(f"aid: {aid['kind']}" + (f" {aid['seconds']} s" if aid.get("seconds") else ""))
                langs = [l for l in ("hi", "hinglish", "mr") if not s["text"].get(l)]
                if langs:
                    todo.append("translation: " + ", ".join(langs))
                src = s["source"]["doc"] + (f" p. {s['source']['page']}" if s["source"].get("page") else "")
                total += 1 if todo else 0
                text = s["text"]["en"].replace("|", "\\|")
                lines.append(f"| `{s['id']}` ({bkey}) | {text} | {src} | {'; '.join(todo) or 'done'} |")
        dn = [d for b in rec["branches"].values() for d in b["do_not"]]
        lines += ["", f"Do-not items to verify: {len(dn)}. Source differences to record: " + ", ".join(d["topic"] for d in rec.get("source_differences", [])) or "none", ""]
    lines += ["## Safety rules marked [VERIFY] (backend/app/safety_rules.py)", "",
              "- Scorpion sting: clinic or hospital at minimum", "- Dog bite: clinic the same day; emergency if bleeding will not stop, deep, or on the face or neck",
              "- Chemical burn: emergency for eyes, face, a large area, or an acid attack",
              "- Thermal burn: emergency if larger than the palm, on face, neck, hands, feet, genitals or joints, or with breathing difficulty",
              "- Unknown bite: treated as a possible snakebite (emergency) and shows the snakebite steps until the type is known",
              "- \"Not sure\" about breathing: treated as not breathing normally (Path A)", "",
              "## Myth set", ""]
    for m in content.myths():
        if not m.get("verified"):
            lines.append(f"- `{m['id']}`: {m['action']['en']} — reason to verify: {m['reason']['en']}")
    lines += ["", f"Open step items: **{total}**", ""]
    OUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {OUT} ({total} steps with open items)")


if __name__ == "__main__":
    main()
